def _proximal(word, limb):
    n = _ORD[word]
    if limb == "hand":
        en, fr, de, es = _HAND[n]
        return (f"proximal phalanx of {word} finger of hand",
                f"Proximal phalanx of {en}", f"Proximal bone of the {en}; its base articulates with the metacarpal head and its head with the middle or distal phalanx.",
                f"Phalange proximale {fr}", f"Os proximal {fr} ; sa base s'articule avec la tête métacarpienne, sa tête avec la phalange moyenne ou distale.",
                f"Grundphalanx des {de}", f"Grundglied des {de}; seine Basis artikuliert mit dem Mittelhandköpfchen, sein Kopf mit dem Mittel- oder Endglied.",
                f"Falange proximal del {es}", f"Hueso proximal del {es}; su base se articula con la cabeza del metacarpiano y su cabeza con la falange media o distal.")
    en, fr, de, es = _FOOT[n]
    return (f"proximal phalanx of {word} finger of foot",
            f"Proximal phalanx of {en}", f"Proximal bone of the {en}; the phalanges of the foot are shorter than those of the hand.",
            f"Phalange proximale {fr}", f"Os proximal {fr} ; les phalanges du pied sont plus courtes que celles de la main.",
            f"Grundphalanx der {de}", f"Grundglied der {de}; die Zehenglieder sind kürzer als die Fingerglieder.",
            f"Falange proximal del {es} del pie", f"Hueso proximal del {es} del pie; las falanges del pie son más cortas que las de la mano.")


